fn build_authenticated_semantic_graph_inner(
    root: &Path,
    entry_module: &str,
    after_render: impl FnOnce(&WorkspaceSemanticGraph),
) -> Result<WorkspaceSemanticGraph, Vec<Diagnostic>> {
